  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      const index = lambda[i] - i + j;
      row.push(supersymmetriccompletehomogeneoussymmetricfunc(index, X, Y));
    }
    M.push(row);
  }
//console.log(M)
