function inversionstatistic(P) {
    let n = leng(P);
    let count = 0;

    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (g(P, i) > g(P, j)) {
                count += 1;
            }
        }
    }

    return count;
}

