function generatepartitionsof(n) {
    const M = [];

    function helper(current, remaining, max) {
        if (remaining === 0) {
            M.push(current.slice());
            return;
        }
        for (let i = Math.min(max, remaining); i >= 1; i--) {
            current.push(i);
            helper(current, remaining - i, i);
            current.pop();
        }
    }

    helper([], n, n);
    return M;
    }

