function leftwardsubword(S) {
    let maxval = 0;
    for (let i = 0; i < leng(S); i++) {
    if (g(S, i) > maxval) maxval = g(S, i);}
    let used = new Array(leng(S)).fill(false);
    let result = [];
    while (used.some(u => !u)) {
        let subword = [];
        let needed = new Set();
        for (let i = 1; i <= maxval; i++) needed.add(i);
        for (let i = leng(S) - 1; i >= 0; i--) {
            if (!used[i] && needed.has(g(S, i))) {
                subword.unshift(g(S, i));
                used[i] = true;
                needed.delete(g(S, i));
            if (needed.size === 0) break;}}
    result.push(subword);}
    return result;
}
function standartsubword(S) {
  let n = leng(S);
    let used = new Array(n).fill(false);
    let maxval = 0;
    for (let i = 0; i < n; i++) if (g(S, i) > maxval) maxval = g(S, i);
    let result = [];
    while (used.some(u => !u)) {
        let indices = [];
        let start = -1;
        for (let i = n - 1; i >= 0; i--) {
            if (!used[i] && g(S, i) === 1) {
                start = i;
                indices.push(i);
                used[i] = true;
            break; }}
        if (start === -1) break; 
        let curr = start;
        for (let target = 2; target <= maxval; target++) {
            let found = false;
            for (let step = 1; step <= n; step++) {
                let i = (curr - step + n) % n;
                if (!used[i] && g(S, i) === target) {
                    indices.push(i);
                    used[i] = true;
                    curr = i;
                    found = true;
                break;}}
        if (!found) break; }
        indices.sort((a, b) => a - b);
        let subS = indices.map(i => g(S, i));
    result.push(subS);}
    return result;
}

