function tableaupow(x, T) {
    const P = [];

    for (let i = 0; i < T.length; i++) {
        for (let j = 0; j < T[i].length; j++) {
            const val = T[i][j];
            if (P[val] === undefined) P[val] = 0;
            P[val] += 1;
        }
    }

    return polynomial(P, x);
}

