function integralold(func, initial, end, input, N = bign) {
    function simpsonsRule(a, b, n) {
		
        const h = div(sub(b, a), n);
		
        let sum = math.complex(0,0); 
        for (let i = 1; i < n; i += 2) {
            sum = add(sum, mul(math.complex(4,0), func(add(a, mul(math.complex(i), h)), input)));
        }
        for (let i = 2; i < n - 1; i += 2) {
            sum = add(sum, mul(math.complex(2,0), func(add(a, mul(math.complex(i), h)), input)));
        }
        return mul(div(h, math.complex(3,0)), sum);
    }
          return simpsonsRule(initial,end, N);
       }
       
       
       
       const _gaussLegendreCache = new Map();

       function integral(func, initial, end, input, N = bign) {
       
    //  return integraladaptives(func, initial, end, input)
     //  return integraladaptive(func, initial, end, input, 1e-5)
    // Precompute Gauss–Legendre nodes & weights for given N
 function gaussLegendreNodesWeights(n) {
    if (_gaussLegendreCache.has(n)) {
        return _gaussLegendreCache.get(n);
    }

    const EPS = 1e-3;
    const x = new Array(n);
    const w = new Array(n);
    const m = Math.floor((n + 1) / 2);

    for (let i = 0; i < m; i++) {
        let z = Math.cos(Math.PI * (i + 0.75) / (n + 0.5));
        let z1, p1, p2, p3, pp;

        do {
            p1 = 1;
            p2 = 0;
            for (let j = 0; j < n; j++) {
                p3 = p2;
                p2 = p1;
                p1 = ((2 * j + 1) * z * p2 - j * p3) / (j + 1);
            }
            pp = n * (z * p1 - p2) / (z * z - 1);
            z1 = z;
            z = z1 - p1 / pp;
        } while (Math.abs(z - z1) > EPS);

        x[i] = -z;
        x[n - i - 1] = z;
        w[i] = 2 / ((1 - z * z) * pp * pp);
        w[n - i - 1] = w[i];
    }

    const res = { x, w };
    _gaussLegendreCache.set(n, res);
    return res;
}

    // Gauss–Legendre integration
    function gaussLegendre(a, b, n) {
        const { x, w } = gaussLegendreNodesWeights(n);
        const halfRange = div(sub(b, a), math.complex(2, 0));
        const midPoint = div(add(a, b), math.complex(2, 0));

        let sum = math.complex(0, 0);
        for (let i = 0; i < n; i++) {
            const xi = add(midPoint, mul(halfRange, math.complex(x[i], 0)));
            sum = add(sum, mul(math.complex(w[i], 0), func(xi, input)));
        }
        return mul(halfRange, sum);
    }

    return gaussLegendre(initial, end, N);
}
       
       function integraladaptives(func, a, b, input, tol = 1e-3) {
    const h = sub(b, a);
    const fa = func(a, input);
    const fb = func(b, input);
    const fc = func(div(math.add(a, b), 2), input);

    // Simpson estimate over [a,b]
    let S = mul(h / 6, math.add(fa, mul(4, fc), fb));

    // Split interval and check error
    const c = div(math.add(a, b), 2);
    const fd = func(div(math.add(a, c), 2), input);
    const fe = func(div(math.add(c, b), 2), input);

    const Sleft = mul(h / 12, math.add(fa, mul(4, fd), fc));
    const Sright = mul(h / 12, math.add(fc, mul(4, fe), fb));

    const err = math.abs(sub(math.add(Sleft, Sright), S));

    if (err < tol) {
        return math.add(Sleft, Sright);
    } else {
        // just one level of recursion
        return math.add(
            integraladaptives(func, a, c, input, tol * 2),
            integraladaptives(func, c, b, input, tol * 2)
        );
    }
}

function integraladaptivecomplex(func, a, b, input, steps = bign,N=bign) {
    let z = a;
    let path = [z];

    let v = div(sub(b, a), math.abs(sub(b, a))); // unit direction
    const L = math.abs(sub(b, a));

    const h = L / steps;

    for (let i = 0; i < steps; i++) {
        const t = i / steps;
        const distToEnd = math.abs(sub(b, z)) / L;

        // Estimate derivative magnitude
        const eps = 1e-6;
        const fz = func(z, input);
        const df = div(
            sub(func(add(z, math.complex(eps,0)), input), fz),
            eps
        );

        const danger = math.abs(fz) + 0.5 * math.abs(df);

        // Steering strength
        const avoidStrength = danger * (1 - distToEnd);
        const attractStrength = 2 * (1 - Math.exp(-5 * (1 - distToEnd)));

        // Rotate away (imaginary multiplication)
        const avoidDir = mul(v, math.complex(0, -1)); // perpendicular
        const attractDir = div(sub(b, z), math.abs(sub(b, z)));

        v = add(
            v,
            add(
                mul(avoidDir, avoidStrength * 0.01),
                mul(attractDir, attractStrength * 0.02)
            )
        );

        // Renormalize
        v = div(v, math.abs(v));

        // Advance
        z = add(z, mul(v, h));
        path.push(z);
    }
function contourIntegral(func, path, input, N = 8) {
    let total = math.complex(0,0);

    for (let i = 0; i < path.length - 1; i++) {
        const a = path[i];
        const b = path[i+1];

        const segment = integral(
            (z,u) => func(z,u),
            a, b,
            input,
            N
        );

        total = add(total, segment);
    }

    return total;
}

    return contourIntegral(func,path,input,N);
}

       
       
       
       function integraladaptive(func, a, b, input, tol = 1e-10, maxDepth = 0) {
    // Gauss–Kronrod 15-point nodes & weights (on [-1,1])
    const xgk = [
        0.0000000000000000,
        0.2077849550078985,
        0.4058451513773972,
        0.5860872354676911,
        0.7415311855993944,
        0.8648644233597691,
        0.9491079123427585,
        0.9914553711208126
    ];
    const wg = [ // Gauss 7-pt weights
        0.1294849661688697,
        0.2797053914892766,
        0.3818300505051189,
        0.4179591836734694
    ];
    const wgk = [ // Kronrod 15-pt weights
        0.2094821410847278,
        0.2044329400752989,
        0.1903505780647854,
        0.1690047266392679,
        0.1406532597155259,
        0.1047900103222502,
        0.06309209262997855,
        0.02293532201052922
    ];

    function integrateRecursive(a, b, depth) {
        const center = div(math.add(a, b), 2);
        const half = div(sub(b, a), 2);

        let gsum = math.complex(0,0);
        let ksum = math.complex(0,0);

        // Kronrod sum (15 points, includes Gauss nodes)
        for (let i = 0; i < xgk.length; i++) {
            const dx = mul(half, math.complex(xgk[i],0));
            const f1 = func(math.add(center, dx), input);
            const f2 = func(sub(center, dx), input);

            ksum = math.add(ksum, mul(math.complex(wgk[i],0), math.add(f1,f2)));

            if (i < wg.length) {
                const w = math.complex(wg[i],0);
                const fgi = math.add(f1,f2); // symmetric
                gsum = math.add(gsum, mul(w, fgi));
            }
        }

        const Ik = mul(half, ksum); // Kronrod estimate
        const Ig = mul(half, gsum); // Gauss estimate

        const err = math.abs(sub(Ik, Ig));

        if (err < tol || depth >= maxDepth) {
            return Ik;
        } else {
            const mid = div(math.add(a,b),2);
            return math.add(
                integrateRecursive(a, mid, depth+1),
                integrateRecursive(mid, b, depth+1)
            );
        }
    }

    return integrateRecursive(a, b, 0);
}
       
       
       
   
function fastTransform(kernel, func, xMax, p, N = bign*2) { const h = xMax * 2 / N; let sum = math.complex(0, 0); for (let i = 1; i < N; i += 2) { let x = -xMax + i * h; sum = add(sum, mul(4, mul(evale(func, {x: x, p: p}), kernel(x)))); } for (let i = 2; i < N - 1; i += 2) { let x = -xMax + i * h; sum = add(sum, mul(2, mul(evale(func, {x: x, p: p}), kernel(x)))); } return mul(h / 3, sum); }




function fastTransform2(kernel, func, xMin, xMax, p, N = mul(bign, 2)) {
    // h = (xMax - xMin) * 2 / N
    const h = div(mul(sub(xMax, xMin), 2), N);
    let sum = math.complex(0, 0);

    // odd indices
    for (let i = 1; i < N; i = add(i, 2)) {
        let x = add(xMin, mul(i, h));
        sum = add(sum, mul(4, mul(evale(func, {x: x, p: p}), kernel(x))));
    }

    // even indices
    for (let i = 2; i < sub(N, 1); i = add(i, 2)) {
        let x = add(xMin, mul(i, h));
        sum = add(sum, mul(2, mul(evale(func, {x: x, p: p}), kernel(x))));
    }

    return mul(div(h, 3), sum);
}




















       
       
       
       

