function sumofdivisors(n) {
  let sum = 0;
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      sum += i;
      let j = n / i;
      if (i !== j) sum += j;
    }
  }
  return sum;
}
function ruler(n) {
    if(!Number.isInteger(n)){
        let x=n;
        let bin = tobinary(x);
     let [intPart = "0", fracPart = "0"] = bin.split('.');

    // check fractional part right to left
    if (fracPart && fracPart.includes('1')) {
        for (let i = fracPart.length - 1; i >= 0; i--) {
            if (fracPart[i] === '1') {
                return -(fracPart.length - i); // negative exponent
            }
        }
    }

    // fraction all zeros → check integer part right to left
    if (intPart && intPart.includes('1')) {
        for (let i = intPart.length - 1; i >= 0; i--) {
            if (intPart[i] === '1') {
                return intPart.length - 1 - i; // exponent
            }
        }
    }

    // number is zero
    return null;
}

    let k = 0;
    while ((n & 1) === 0) {
        n >>= 1;
        k++;
    }
    return k;
}
function generalizedruler(n, p) {
    let k = 0;
    while (n % p === 0 && n > 0) {
        n /= p;
        k++;
    }
    return k;
}

function kempner(n) {
    if (n <= 1) return 1;

    const factors = {};
    let x = n;
    for (let p = 2; p * p <= x; p++) {
        while (x % p === 0) {
            factors[p] = (factors[p] || 0) + 1;
            x /= p;
        }
    }
    if (x > 1) factors[x] = (factors[x] || 0) + 1;
    function vp(m, p) {
        let s = 0;
        while (m > 0) {
            m = Math.floor(m / p);
            s += m;
        }
        return s;
    }
    function minM(p, e) {
        let lo = 0, hi = p * e;
        while (lo < hi) {
            const mid = Math.floor((lo + hi) / 2);
            if (vp(mid, p) >= e) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    let ans = 0;
    for (const p in factors) {
        ans = Math.max(ans, minM(+p, factors[p]));
    }
    return ans;
}

function sumofodddivisors(n) {
  let sum = 0;
  for (let i = 1; i * i <= n; i += 2) {
    if (n % i === 0) {
      sum += i;
      let j = n / i;
      if (i !== j && j % 2 === 1) sum += j;
    }
  }
  return sum;
}

function sumofdivisorsk(n, k = 1) {
  let sum = 0;
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      sum += i ** k;
      let j = n / i;
      if (i !== j) sum += j ** k;
    }
  }
  return sum;
}

