function jordantotient(n, k = 1) {
    let result = pow(n, k);
    let factor = 2;

    while (factor * factor <= n) {
        if (n % factor === 0) {
            result = mul(result,sub(1 ,div( 1 , pow(factor, k))));
            while (n % factor === 0) {
                n /= factor;
            }
        }
        factor++;
    }

    if (n > 1) result = mul(result,(sub(1 , div(1 , pow(n, k))))); // Remaining prime factor

    return result;
}
function carmichael(n) {
    if (n === 1) return 1;

    let result = 1;
    let factor = 2;

    while (factor * factor <= n) {
        if (n % factor === 0) {
            let power = 1;
            while (n % factor === 0) {
                n /= factor;
                power *= factor;
            }
            power /= factor;
            let lambda = (factor === 2 && power > 1) ? power / 2 : power;
            result = lcm(result, lambda);
        }
        factor++;
    }

    if (n > 1) result = lcm(result, n - 1); // Remaining prime factor

    return result;
}
