function mangoldt(n) {
    if (n < 2) return 0;

    let factor = 2;
    while (factor * factor <= n) {
        if (n % factor === 0) {
            while (n % factor === 0) n /= factor;
            return n === 1 ? log(factor) : 0;
        }
        factor++;
    }

    return log(n); // n itself is prime
}
