function landau(n) {
    const dp = Array(n + 1).fill(0);
    dp[0] = 1;

    for (let k = 1; k <= n; k++) {
        const bk = (k);
        for (let s = n; s >= k; s--) {
            const candidate = lcm(dp[s - k], bk);
            if (candidate > dp[s]) dp[s] = candidate;
        }
    }
    return dp[n];
}
