function liouville(n) {
    let factorCount = 0;
    let factor = 2;
    while (factor * factor <= n) {
        while (n % factor === 0) {
            n /= factor;
            factorCount++;
        }
        factor++;
    }
    if (n > 1) factorCount++;
    return factorCount % 2 === 0 ? 1 : -1;
}
function distinctprimefactors(n) {
    let count = 0;
    let factor = 2;
   while (factor * factor <= n) {
        if (n % factor === 0) {
            count++;
            while (n % factor === 0) {
                n /= factor;
            }
        }
        factor++;
    }
    if (n > 1) count++; 
    return count;
}
function primefactors(n) {
    let factors = [];
    let factor = 2;

    while (factor * factor <= n) {
        while (n % factor === 0) {
            factors.push(factor);
            n /= factor;
        }
        factor++;
    }

    if (n > 1) factors.push(n);

    return factors;
}
function totalprimefactors(n) {
    let count = 0;
    let factor = 2;
    while (factor * factor <= n) {
        while (n % factor === 0) {
            n /= factor;
            count++;
        }
        factor++;
    }
    if (n > 1) count++; 

    return count;
}




