function lptransform2(func,func2,b) {
    const xf = b.re;
    const yf = b.im;
    const ss = Math.sqrt(xf * xf + yf * yf);
    const ata = Math.atan2(yf, xf);
    return math.complex(
        ss * evale(func,{x:ata,p:b,s:ss}),
        ss * evale(func2,{x:ata,p:b,s:ss})
    );
}



