function danduseppoly(x,a){return add(tesseract(x),mul(-1,cum(x)),mul(x,x,sub(a,1)),mul(x,sub(mul(3,a),8)),a,a)}
function danduseqpoly(x,a){return add(mul(2,x,x,x),mul(-1,x,x),mul(x,2,sub(a,14)),a,a,a,a,a,a,a)}
