function dotc(a, b) {
    const aComp = math.complex(a);
    const bComp = math.complex(b);
    return add(mul(aComp.re, bComp.re), mul(aComp.im, bComp.im));
}

function crossc(a, b) {
    const aComp = math.complex(a);
    const bComp = math.complex(b);
    return sub(mul(aComp.re, bComp.im), mul(aComp.im, bComp.re));
}

