    function entringernum(n,k){
        if(Number.isInteger(n) && Number.isInteger(k)){
            
        if (k < 0 || k > n || n < 0) return 0;

  
    const E = Array.from({ length: n + 1 }, (_, i) =>
        Array(i + 1).fill(0)
    );

    E[0][0] = 1;

    for (let i = 1; i <= n; i++) {
        E[i][0] = 0;
        for (let j = 1; j <= i; j++) {
            E[i][j] = E[i][j - 1] + E[i - 1][i - j];
        }
    }

    return E[n][k];    
            
        }
    return entringerzag(k,sub(n,k))
    }
    
