function flowpoly(G,k){return mul(pow(-1,sub(add(edgecount(G),connectedcomponents(G)),leng(G))),tuttepoly(G,sub(1,k)))}
function reliabilitypoly(G,p){return mul(pow(sub(1,p),sub(leng(G),connectedcomponents(G))),pow(p,add(sub(edgecount(G),leng(G)),connectedcomponents(G))),tuttepoly(G,1,div(1,p)))}
function coranknullitypoly(G,u,v){return mul(pow(u,connectedcomponents(G)),reliabilitypoly(G,p))}
