function simplifypairized(pairs) {
     let changed = true;

    while (changed) {
        changed = false;

        for (let i = 0; i < pairs.length - 2; i++) {

            let [q, a] = pairs[i];
            let [b, c] = pairs[i+1];
            let [d, r] = pairs[i+2];

            if (a === b && b === -c && c === d) {
                pairs.splice(i, 3, [q, r]);
                changed = true;
                break;
            }
            if (a === -b && b === -c && c === -d) {

                let n = -a;
                let m = -c;

                let exists = false;

                for (let j = 0; j < pairs.length; j++) {
                    if (j === i || j === i+1 || j === i+2) continue;

                    let [x,y] = pairs[j];
                    if (
                        (x === n && y === m) ||
                        (x === m && y === n)
                    ) {
                        exists = true;
                        break;
                    }
                }

                if (exists) {
                    pairs.splice(i, 3, [q, r]);
                    changed = true;
                    break;
                }
            }
            
    for (let i = 0; i < pairs.length; i++) {
        let [a, b] = pairs[i];

        for (let j = i + 1; j < pairs.length; j++) {
            let [c, d] = pairs[j];

            // check if [a,b] and [-a,-b]
            if (c === -a && d === -b && signum(a)==signum(b)) {
        //    console.log(a,b,c,d)
                // remove both
                pairs.splice(j, 1);
                pairs.splice(i, 1);

                // merge strand b into a
                for (let k = 0; k < pairs.length; k++) {
                    let [x, y] = pairs[k];

                    if (x === b) x = a;
                    if (x === -b) x = -a;

                    if (y === b) y = a;
                    if (y === -b) y = -a;

                    pairs[k] = [x, y];
                }

                changed = true;
                    break;
            }
        }
    }
        }
    }

    return pairs;
}




