function r1bw(bw){
let k=[]
for(let i=0;i<leng(bw);i++){
let x=g(bw,i)
if(i<leng(bw)-1&&g(bw,i+1)==-x){i++;continue}
if(i>0&&g(bw,i-1)==-x)continue
k.push(x)
}return k
}

function r2bw(bw){
let changed=true
while(changed){
changed=false
for(let i=0;i<leng(bw)-1;i++){
let x=g(bw,i)
let y=g(bw,i+1)
if(abs(re(x))==abs(re(y))&&re(x)==-re(y)){
bw.splice(i,2)
changed=true
break
}}}
return bw
}
function r3bw(bw){
for(let i=0;i<leng(bw)-2;i++){
let x=g(bw,i),y=g(bw,i+1),z=g(bw,i+2)
let ix=abs(re(x)),iy=abs(y),iz=abs(z)
let sx=signum(x),sy=signum(y),sz=signum(z)
if(ix==iz&&abs(ix-iy)==1&&iy!=ix){
bw[i]=y
bw[i+1]=x
bw[i+2]=z
}}
return bw
}

