function connectedcomponents(G){G=rearray(G)
  let n=G.length;
  let visited=new Array(n).fill(false);
  let count=0;
  for(let i=0;i<n;i++){
    if(!visited[i]){
      count++;
      let stack=[i];
      visited[i]=true;
      while(stack.length){
        let v=stack.pop();
        for(let j=0;j<n;j++){
          if(G[v][j]&&!visited[j]){
            visited[j]=true;
            stack.push(j);
          }
        }
      }
    }
  }
  return count;
}
