function rank(A){
  
  let n = A.length;
  let m = A[0].length;
  let M = A.map(row => row.map(x=>x)); 
  let rank = 0;

  for(let col=0,row=0; col<m && row<n; col++){
    let pivotRow = -1;
    for(let i=row;i<n;i++){
      if(re(M[i][col])!==0 || im(M[i][col])!==0){ pivotRow=i; break; }
    }
    if(pivotRow==-1) continue;
    if(pivotRow!==row){
      let tmp = M[row]; M[row]=M[pivotRow]; M[pivotRow]=tmp;
    }
    let pivot = M[row][col];
    for(let j=col;j<m;j++) M[row][j] = div(M[row][j], pivot);
    for(let i=0;i<n;i++){
      if(i===row) continue;
      let factor = M[i][col];
      for(let j=col;j<m;j++){
        M[i][j] = sub(M[i][j], mul(factor, M[row][j]));
      }
    }
    row++;
    rank++;
  }
  return rank;
}






