function modexp(base, ex, mod) {
    return modc(pow(base,ex),mod)
let result = math.complex(1,0);
  base = modc(base , mod);
  while (re(ex) > 0) {
  if (modc(ex , 2) === 1) {
      result = modc(mul(result , base) , mod);
    }
    ex = floor(div(ex , 2));
  base = modc(mul(base , base) , mod);
  }
  return result;
}

