// Dirichlet Eta function
function dirichleteta(b) {
    let t = math.complex(0);
    let fi = math.complex(0);
    
    for (let i = 0; i < bign; i++) {
        t = math.complex(0);
        for (let j = 0; j <= i; j++) {
            t = add(t, mul(ncr(i, j), div(pow(-1.0, j), pow(j + 1.0, b))));
        }
        fi = add(fi, div(t, pow(2.0, i + 1.0)));
    }
    
    return fi;
}
