    let a = [1];
    let b = [sqrt(sub(1, sqr(k)))];
    let c = [k];

    for (let n = 1; n <= bign; n++) {
        a.push(div(add(a[n - 1], b[n - 1]), 2));
        b.push(sqrt(mul(a[n - 1], b[n - 1])));
    }

    return div(pi(), 2, a[bign]);
