    function somos4int(n,V=[1,1,1,1]){
let a=rearray(V)
let k=leng(a)
if(n<k)return g(a,n)
for(let i=k;i<=n;i++){
let t=div(add(mul(g(a,i-1),g(a,i-3)),mul(g(a,i-2),g(a,i-2))),g(a,i-4))
a[i]=t
}
return g(a,n)
}

