function squaremod(x, ll=1.76663875) {
	const l=mul(0.5,ll);
    const w = exp(div(mul(2, pi(), I), 4)); // 120-degree rotation
    let fi = sub(div(l), modc(add(x, div(l)), mul(l, 2)));
    fi = mul(fi, w);
    fi = sub(l, modc(add(fi, l), mul(l, 2)));
    fi = mul(fi, w);
    fi = sub(l, modc(add(fi, l), mul(l, 2)));
    fi = mul(fi, w);
    fi = sub(l, modc(add(fi, l), mul(l, 2)));
    fi = mul(fi, w);
    fi = sub(l, modc(add(fi, l), mul(l, 2)));
   
    return sub(0, fi); // Negative result
}
