function qpocinf(a, q=a) {
    let fi = math.complex(1.0, 0);
    for (let i = 0; i < bign; i++) {
        fi = mul(fi, sub(math.complex(1.0, 0), mul(a, pow(q, i))));
    }
    return fi;
}
function qpochinf(a, q=a) {//same thing 
    if(a==q)return eulerfunc(q);
    let fi = math.complex(1.0, 0);
    for (let i = 0; i < bign; i++) {
        fi = mul(fi, sub(math.complex(1.0, 0), mul(a, pow(q, i))));
    }
    return fi;
}
