function besseljd(u,Z){
    const z=g(Z,0);const n=g(Z,1);
return mul(pow(sin(u),mul(2,n)),cos(mul(z,cos(u))));
}

function besselj(a, b) {
        let term = div(pow(div(b, 2), a), gamma(add(a, 1)));
    let sum  = term;
    for (let n = 0; n < 1000; n++) {
        term = mul(term,
            div(
                mul(-1, pow(div(b, 2), 2)),
                mul(add(n, 1), add(n, a, 1))
            )
        );
        sum = add(sum, term);
        if (norm(term) < 1e-14 * norm(sum)) break;
    }
    return sum;
}
