function ellipticmembrane(e,mu,v,m,n,t=0,c=1,a=1){
    let mu0=atanh(e)
    let f=mul(a,sqrt(sub(1,sqr(e))))
    let q=mathieucczero(mu0,m,n)
    let w=div(mul(2,c,sqrt(q)),f)
    return mul(mathieucce(q,mu,n),mathieuce(q,v,n),cos(mul(w,t)))
}
 
