function besselyp(a, b) {
    // Y'_a(b) = (Y_{a-1}(b) - Y_{a+1}(b)) / 2
    let h=0.001;
    return div(
        sub(
            bessely(sub(a, h), b),
            bessely(add(a, h), b)
        ),
        2,h
    );
}

