function lambertwfn(x,n,nn=bign){
    
    let fi=0
    let w=add(mul(2,n,I,pi()),log(x))
    let z=log(w)
    for(let nnn=1;nnn<nn;nnn++)
    {let fid=0
       for(let m=1;m<=nnn;m++)
fid=add(fid,div(mul(pow(z,m),stirling(sub(nnn,m,-1),nnn)),factorial(m)))           
fi=add(fi,mul(fid,pow(-1,nnn),pow(w,sub(0,nnn))))
    }
    return sub(w,z,fi)
}

