            const L2 = filog(b,-1) //div(wrightw2(add(log(log(b)),mul(I,pi()))),-1,log(b))//(mag(im(b))<1)?filog(b,-1):div(wrightw2(add(log(log(b)),mul(I,pi()))),-1,log(b));
