            let psi1=(x)=>{return (mag(s1)<1)?div(log(mul(pow(s1,sub(0,N)),sub(powertower(b,N,x),L1))),log(s1)):div(log(mul(pow(s1,N),sub(logtower(b,N,x),L1))),log(s1))}
