function pent2u(x){
       const L=  -1.7439;
       const Lp= 5.171797;

       let fi=sub(L,pow(Lp,add(x,1,sub(0,6),div(log(L),log(Lp)))));
       ;
       for(let i=0;i<6;i++)
           fi=tetr2(fi);
       return fi;
    }
    function pent2c(x){return pent2u(add(x,0.7179548082276691))}
        function pent2(x){
        if(re(x)<0) return pent2c(x)
        let fi=pent2c(add(0,modc(x,1)))
        for(let i=0;i<minc(9,re(floor(re(x))));i++)
        fi=tetr2(fi);
        return fi;
    }

