function pentalogs2(x){
           const L=  -1.5702829859249143;
       const Lp= 4.814318974588616;
       let fi=x;
        for(let i=0;i<3;i++)
           fi=slogs2(fi);
        fi=add(div(log(div(sub(L,fi),L)),log(Lp)),2)
       return add(fi,-0.45);
}

