    function margin(x,N=bign/2){
       if(re(x)<0)return sub(0,x) 
    if(N<=0)return x;
let M=sub(N,2)
return div(margin(sub(x,margin(sub(x,1),M),div(-1,getdenom(add(margin(sub(x,1),M),x,-1))),pow(2,ceil(log2(margin(sub(x,1),M))))),M),2)
    }
    
