function filog(b,n=0) {
    // Convert b to a complex number if necessary
    let logB = math.log(b);
    let lambertW = lambertw(sub(0,logB),n);
    let r= div(sub(0,lambertW), logB);
    if(re(b)==b)
        return conj(r)
    return r
}
function gilog(b,n=0) {//x^(1/x)^(1/x)..
    return div(log(b),lambertw(log(b),n));
}







