function evalanalytic(func, z, z0=0,terms = bign/2) {
    let steps = terms;
    let delta = math.divide(math.subtract(z, z0), steps);
    let points = Array.from({ length: steps + 2 }, (_, i) =>
        math.add(z0, math.multiply(i, delta) )
    );

    // Start with the initial point
    let result = z0;

    // Successively apply evaltaylor along each intermediate point
    for (let i = 0; i <= steps; i++) {
        result = evaltaylor(func, points[i+1], points[i], terms);
    }

    return result;
}
function solvelinear(A,b){
  let n = b.length;
    let eps = 1e-14;

    for(let i=0;i<n;i++){
        // pivot
        let piv = i;
        for(let k=i;k<n;k++){
            if(Math.abs(A[k][i].re ?? A[k][i]) > eps){
                piv = k; break;
            }
        }

        if(piv !== i){
            let t=A[i]; A[i]=A[piv]; A[piv]=t;
            t=b[i]; b[i]=b[piv]; b[piv]=t;
        }

        if(Math.abs(A[i][i].re ?? A[i][i]) < eps){
            return null; // singular system
        }

        let inv = div(1,A[i][i]);
        for(let j=i;j<n;j++) A[i][j]=mul(A[i][j],inv);
        b[i]=mul(b[i],inv);

        for(let k=0;k<n;k++){
            if(k===i) continue;
            let f=A[k][i];
            for(let j=i;j<n;j++){
                A[k][j]=sub(A[k][j],mul(f,A[i][j]));
            }
            b[k]=sub(b[k],mul(f,b[i]));
        }
    }
    return b;
}

const _padeCache = new Map();

function evalpade(func, x, z0=0, N=5,hh=1.5){
    // build a key for caching based on function reference, z0, N
    let key = func + '|' + z0 + '|' + N + hh;

    // retrieve memoized coefficients if available
    let memo = _padeCache.get(key);
    let a, q, p;

    if(memo){
        a = memo.a;
        q = memo.q;
        p = memo.p;
    } else {
        // compute coefficients
        a = rearray(getcoefseries(func, z0, N*2+1,hh));

        // build Padé denominator system
        let A = [];
        let b = [];
        for(let k=N+1;k<=2*N;k++){
            let row = [];
            for(let j=1;j<=N;j++){
                row.push(a[k-j]);
            }
            A.push(row);
            b.push(sub(0,a[k]));
        }

        // solve for denominator
        q = solvelinear(A,b);
        if(!q) return NaN;
        q.unshift(1);

        // numerator coefficients
        p = [];
        for(let k=0;k<=N;k++){
            let s = 0;
            for(let j=0;j<=k;j++){
                s = add(s, mul(a[k-j], q[j]));
            }
            p.push(s);
        }

        // memoize
        _padeCache.set(key, {a,q,p});
    }

    // evaluate rational function at x
    let dx = sub(x,z0);
    let num = 0, den = 0;
    for(let i=0;i<p.length;i++){
        num = add(num, mul(p[i], pow(dx,i)));
        den = add(den, mul(q[i], pow(dx,i)));
    }

    return div(num,den);
}

const _taylorPadeCache = new Map();

function evaltaylorpade(F, x, z0=0){
    let N = Math.floor(sub(div(leng(F),2),1));
    let key = F + '|' + z0 + '|' + N;
    let memo = _taylorPadeCache.get(key);
    let a=F, q, p;

    if(memo){
        q = memo.q;
        p = memo.p;
    } else {
        let A=[], b=[];
        for(let k=N+1;k<=2*N;k++){
            let row=[];
            for(let j=1;j<=N;j++) row.push(a[k-j]);
            A.push(row);
            b.push(sub(0,a[k]));
        }
        q = solvelinear(A,b);
        if(!q) return NaN;
        q.unshift(1);
        p=[];
        for(let k=0;k<=N;k++){
            let s=0;
            for(let j=0;j<=k;j++) s=add(s,mul(a[k-j],q[j]));
            p.push(s);
        }
        _taylorPadeCache.set(key,{q,p});
    }

    let dx=sub(x,z0), num=0, den=0;
    for(let i=0;i<=N;i++){
        num=add(num,mul(p[i],pow(dx,i)));
        den=add(den,mul(q[i],pow(dx,i)));
    }
    return div(num,den);
}





