	function harmoniclog(n,t,x){
		let fi=math.complex(0,0);
		for(let j=0;j<=math.complex(t).re;j++)
			fi=add(fi,mul(pow(-1,j),pochhammer(t,j),pow(math.log(x),sub(t,j)),twoindexharmonic(n,j)));
		return mul(pow(x,n),fi);
	}
