function g(A, n ,w=0) {
	if(leng(A)<=n)return 0;
    try {
        if (A._data !== undefined) {
			if(A._data[n]!== undefined)
				return A._data[n];
			return w;
		}
        if(A[n]!== undefined)
				return A[n];
			return w;
    } catch (e) {
        return w;
    }
}
function rearray(A, w = 0) {
    const result = [];
    const length = leng(A);

    for (let i = 0; i < length; i++) {
        result.push(g(A, i, w)); 
    }

    return result;
}

