function multivariatepolynomial(P, X) {
    let result = 0;
    for (let i = 0; i < leng(P); i++) {
        let [exponents, coeff] = P[i];
        let term = coeff;
        for (let j = 0; j < leng(X); j++) {
            term = mul(term, pow(g(X, j), g(exponents, j)));
        }
        result = add(result, term);
    }
    return result;
}




