function adim(W){
    let N=leng(W),fi=1
    for(let i=1;i<=N;i++)
    for(let j=i+1;j<=N+1;j++){
        let s=0
        for(let k=i;k<j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(s,j-i),j-i))}
    return fi}

function bdim(W){
    let N=leng(W),fi=1
    for(let i=1;i<=N;i++)
    for(let j=i;j<=N;j++){
        let s=0
        for(let k=i;k<=j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(s,j-i+1),j-i+1))}
    for(let i=1;i<N;i++)
    for(let j=i+1;j<=N;j++){
        let s=0
        for(let k=i;k<j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(add(s,g(W,j)),add(g(W,j),2*N-j-i+1)),2*N-j-i+1))}
    return fi}

function cdim(W){
    let N=leng(W),fi=1
    for(let i=1;i<=N;i++)
    for(let j=i;j<=N;j++){
        let s=0
        for(let k=i;k<=j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(s,j-i+1),j-i+1))}
    for(let i=1;i<N;i++)
    for(let j=i+1;j<=N;j++){
        let s=0
        for(let k=i;k<j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(add(s,2*g(W,j)),2*N-j-i+2),2*N-j-i+2))}
    return fi}

function ddim(W){
    let N=leng(W),fi=1
    for(let i=1;i<=N-2;i++)
    for(let j=i;j<=N-2;j++){
        let s=0
        for(let k=i;k<=j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(s,j-i+1),j-i+1))}
    for(let i=1;i<N;i++)
    for(let j=i+1;j<=N;j++){
        let s=0
        for(let k=i;k<j;k++)s=add(s,g(W,k))
        fi=mul(fi,div(add(s,add(g(W,j),2*N-j-i)),2*N-j-i))}
    return fi}





