function hypergeometriclambda(E,V,F,P,k,a){
let fi=1;for(let i=0;i<leng(E);i++)fi=mul(fi,add(g(E,i),mul(g(V,i),k)))
         for(let i=0;i<leng(F);i++)fi=div(fi,add(g(F,i),mul(g(P,i),k)))
         return mul(fi,div(pow(a,k),factorial(k)))
}

