function retry (func,x,n){
	let fi=math.complex(0,0);
	for(let i=0;i<n;i++)
	fi = add(fi,evale(func,{x:x,i:i,n:n}));
	return div(fi,n);
}
function retrymin (func,x,n){
	let fi=math.complex(0,0);
	for(let i=0;i<n;i++)
	fi = minc(fi,evale(func,{x:x,i:i,n:n}));
	return div(fi,n);
}
function retrymax (func,x,n){
	let fi=math.complex(0,0);
	for(let i=0;i<n;i++)
	fi = maxc(fi,evale(func,{x:x,i:i,n:n}));
	return div(fi,n);
}


