function upperplanemobiustransform(a,z){return div(add(mul(sub(1,mul(I,a)),z),conj(a),mul(-1,I)),add(mul(add(sqr(mag(a)),mul(conj(a),I)),z),mul(I,sqr(mag(a))),a))}
