function sylvestermatrix(P,Q) {
  const m = sub(leng(P),1);
  const n = sub(leng(Q),1);
  const size = add(m,n);
  const M = Array.from({ length: size },() => Array(size).fill(0));
  for (let i = 0; i < n; i++)
    for (let j = 0; j <= m; j++)
      M[i][add(size - m - i - 1,j)] = g(P,j);
  for (let i = 0; i < m; i++)
    for (let j = 0; j <= n; j++)
      M[add(i,n)][add(size - n - i - 1,j)] = g(Q,j);
  return M;
}

function resultant(P,Q) {
  return determinant(sylvestermatrix(P,Q));
}

function discriminant(P) {
  const n = sub(leng(P), 1);
  const a_n = g(P, n);
  const dP = polynomialderv(P);
  const R = resultant(P, dP);
  const k = div(mul(n, sub(n, 1)), 2);
  const sign = (k % 2 === 0) ? -1 : 1;
  return div(mul(sign, R), a_n);
}


function bezoutmatrix(P,Q){
  const n = sub(Math.max(leng(P), leng(Q)), 1);
  const B = Array.from({ length: n }, () => Array(n).fill(0));

  // Compute coefficients
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let s = 0;
      for (let k = add(i,1); k < leng(P); k++) {
        const term1 = mul(g(P, k), g(Q, add(j,1)));
        const term2 = mul(g(P, add(j,1)), g(Q, k));
        s = add(s, sub(term1, term2));
      }
      B[i][j] = s;
    }
  }
  return B;
}

function transfermatrix(P) {
  const n = sub(leng(P), 1);
  const a_n = g(P, n);
  const T = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 1; i < n; i++) {
    T[i][sub(i,1)] = 1;
  }
  for (let i = 0; i < n; i++) {
    T[i][sub(n,1)] = div(-g(P, i), a_n);
  }
  return T;
}


function alternantmatrix(f, n, m,z=0) {
  const A = Array.from({ length: n }, () => Array(m).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      A[i][j] = evale(f,{ x: i, y: j ,z:z});
    }
  }
  return A;
}

function alternantdeterminant(f,n,z=0){
    return determinant(alternantmatrix(f, n, n , z))
}
function diagonalmatrix(V) {
  const n = leng(V);
  const M = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    g(M, i)[i] = g(V, i);
  }
  return M;
}
function identitymatrix(n) {
  
  const M = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    g(M, i)[i] = 1;
  }
  return M;
}
function antidiagonalmatrix(V) {
  const n = leng(V);
  const M = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    const j = sub(sub(n, 1), i);
    g(M, i)[j] = g(V, i);
  }
  return M;
}

function arrowheadmatrix(V, D, H) {
  const n = leng(D);
  const M = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) g(M, i)[i] = g(D, i);
    for (let i = 1; i < n; i++) g(M, i)[0] = g(V, i-1);
    for (let j = 1; j < n; j++) g(M, 0)[j] = g(H, j-1);
  return M;
}
function exchangematrix(n) {
  const J = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    const j = sub(sub(n, 1), i);
    g(J, i)[j] = 1;
  }
  return J;
}
function matrixexchange(M) {
  const n = leng(M);
  const J = exchangematrix(n);
  const R = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let s = 0;
      for (let k = 0; k < n; k++) {
        s = add(s, mul(g(g(M, i), k), g(g(J, k), j)));
      }
      g(R, i)[j] = s;
    }
  }
  return R;
}
function bidiagonalmatrixmatrix(U, M) {
  const n = leng(M);
  const B = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    g(B, i)[i] = g(M, i);
    if (i < sub(n, 1)) g(B, i)[add(i, 1)] = g(U, i);
  }
  return B;
}
function lowerbidiagonalmatrix(M, D) {
  const n = leng(M);
  const B = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    g(B, i)[i] = g(M, i);
    if (i > 0) g(B, i)[sub(i, 1)] = g(D, sub(i, 1));
  }
  return B;
}
function tridiagonalmatrix(U, M, D) {
  const n = leng(M);
  const T = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    g(T, i)[i] = g(M, i);
    if (i > 0) g(T, i)[sub(i, 1)] = g(D, sub(i, 1));
    if (i < sub(n, 1)) g(T, i)[add(i, 1)] = g(U, i);
  }
  return T;
}

function symmetricmatrix(A) {
  const n = leng(A);
  const S = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j <= i; j++) {
      g(S, i)[j] = g(S, j)[i] = g(A, i)[j];
    }
  }
  return S;
}
function antisymmetricmatrix(A) {
  const n = leng(A);
  const S = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) g(S, i)[j] = 0;
      else g(S, i)[j] = sub(0, g(A, j)[i]);
    }
  }
  return S;
}
function bisymmetricmatrix(A) {
  const n = leng(A);
  const B = symmetric(A);
  const BS = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      g(BS, i)[j] = g(B, sub(n, add(i, 1)))[sub(n, add(j, 1))];
    }
  }
  return symmetric(BS);
}
function centrosymmetricmatrix(A) {
  const n = leng(A);
  const C = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      g(C, i)[j] = g(A, sub(n, add(i, 1)))[sub(n, add(j, 1))];
    }
  }
  return C;
}
function persymmetricmatrix(A) {
  const n = leng(A);
  const P = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      g(P, i)[j] = g(A, sub(n, add(j, 1)))[sub(n, add(i, 1))];
    }
  }
  return P;
}
//gmul(transpose(orthogonalmatrix([[1,2],[3,4]])),orthogonalmatrix([[1,2],[3,4]]))
function orthogonalmatrix(A) {
  const n = leng(A);
  const Q = Array.from({ length: n }, () => Array(n).fill(0));

  for (let j = 0; j < n; j++) {
    // Copy column j from A
    for (let i = 0; i < n; i++) g(Q, i)[j] = g(A, i)[j];

    // Subtract projections onto previous columns
    for (let k = 0; k < j; k++) {
      let dot = 0;
      for (let i = 0; i < n; i++) dot = add(dot, mul(g(Q, i)[j], g(Q, i)[k]));
      for (let i = 0; i < n; i++) g(Q, i)[j] = sub(g(Q, i)[j], mul(dot, g(Q, i)[k]));
    }

    // Normalize column
    let norm = 0;
    for (let i = 0; i < n; i++) norm = add(norm, pow(g(Q, i)[j], 2));
    norm = pow(norm, div(1, 2));
    for (let i = 0; i < n; i++) g(Q, i)[j] = div(g(Q, i)[j], norm);
  }

  return Q;
}
function semiorthogonalmatrix(A) {
  const m = leng(A);
  const n = leng(g(A,0));
  const Q = Array.from({ length: m }, () => Array(n).fill(0));

  for (let j = 0; j < n; j++) {
    for (let i = 0; i < m; i++) g(Q, i)[j] = g(A, i)[j];

    for (let k = 0; k < j; k++) {
      let dot = 0;
      for (let i = 0; i < m; i++) dot = add(dot, mul(g(Q, i)[j], g(Q, i)[k]));
      for (let i = 0; i < m; i++) g(Q, i)[j] = sub(g(Q, i)[j], mul(dot, g(Q, i)[k]));
    }

    let norm = 0;
    for (let i = 0; i < m; i++) norm = add(norm, pow(g(Q, i)[j], 2));
    norm = pow(norm, div(1, 2));
    for (let i = 0; i < m; i++) g(Q, i)[j] = div(g(Q, i)[j], norm);
  }

  return Q;
}














