function polyvectormap(func, ...X) {
  const n = leng(g(X, 0));
  return Array.from({ length: n }, (_, i) => {
    const scope = { x: g(g(X,0), i) };
    for (let k = 1; k < X.length; k++)
      scope["x" + k] = g(g(X,k), i);
    return evaluate(func, scope);
  });
}
