function mathieuke(q,z,nn=0,s=0,rr=nn){
    if(modc(nn,2)==0)
    return  mathieuke2(mathieul(q,rr),q,z,s,nn)
    return  mathieuke1(mathieul(q,sub(0,rr)),q,z,s,nn)
}
