function colmatrix(arr) {
  const n = leng(arr);
  const C = Array.from({ length: n }, () => [0]);
  for (let i = 0; i < n; i++) {
    g(C, i)[0] = g(arr, i);   // 1 column
  }
  return C;
}
function rowmatrix(arr) {
  const n = leng(arr);
  const R = [ Array(n).fill(0) ];
  for (let j = 0; j < n; j++) {
    R[0][j] = g(arr, j);
  }
  return R;
}

